function modalView(){
 if(s.modal==='project'){const p=s.project||{};return '<div class="overlay"><form class="modal" data-form="project"><header><h2>'+e(p.id?'Edit project':'New project')+'</h2>'+action('close','×')+'</header><div class="form-grid">'+input('Project name','name',p.name,'text','required')+input('Jobsite address','address',p.address,'text','required')+input('Client','client',p.client)+input('E-mail','email',p.email,'email')+input('Phone','phone',p.phone)+input('Endereço of cobrança','billingAddress',p.billingAddress)+input('Salesperson','salesperson',p.salesperson||s.settings.company.salesperson)+'</div><label>Notes<textarea name="notes">'+e(p.notes)+'</textarea></label><button class="primary">Save & create estimate</button></form></div>';}
 if(s.modal==='upload'){const u=s.upload||{},p=u.preview;
  return '<div class="overlay"><form class="modal" data-form="upload"><header><h2>Import permit file</h2>'+action('close','×')+'</header><p class="muted">PDF, CSV or XLSX of the municipal report. Check the preview before saving; the import is marked as partial.</p><div class="form-grid"><label>City<select name="sourceId">'+s.sources.map(c=>opt(c.id,c.city+' · '+c.state,u.sourceId)).join('')+'</select></label>'+input('From month','month',u.month||previous,'month','required')+input('To month (optional, for files with several months)','toMonth',u.toMonth||'','month')+'<label>File<input name="file" type="file" accept=".pdf,.csv,.xlsx,application/pdf,text/csv"></label></div>'+(u.file?'<p class="muted">Selected file: '+e(u.file.name)+' ('+n(u.file.size/1024,0)+' KB)</p>':'')+'<button class="primary">Show preview</button>'+(p?'<div class="panel"><h3>Preview</h3><p>Format '+e({pdf:'PDF',xlsx:'Excel',html:'HTML',text:'CSV/text'}[p.format]||p.format)+' · '+p.rowsRead+' rows read · <b>'+p.inMonth+' permits in '+e(u.month)+(p.toMonth>u.month?' to '+e(p.toMonth):'')+'</b>'+(p.outsideMonth?' · '+p.outsideMonth+' outside the month (ignored)':'')+(p.undated?' · '+p.undated+' without date':'')+(p.approx?' · '+p.approx+' use the month (approximate date)':'')+(p.invalid?' · '+p.invalid+' invalid':'')+'</p>'+(p.cityHint?'<div class="warning">Most addresses in this file look like <b>'+e(p.cityHint.city)+', '+e(p.cityHint.state)+'</b>, not '+e((s.sources.find(c=>c.id===u.sourceId)||{}).city||'the selected city')+'. '+action('useCity','Switch to '+p.cityHint.city,p.cityHint.id)+'</div>':'')+(p.monthHint?'<div class="warning">The permits in this file are from <b>'+e(p.monthHint)+'</b>, not '+e(u.month)+'. '+action('useMonth','Use '+p.monthHint,p.monthHint)+'</div>':'')+(p.toMonth>u.month&&p.months?'<p class="muted">By month: '+Object.entries(p.months).sort().map(([m,c])=>e(m)+': '+c).join(' · ')+'</p>':'')+(p.tooOld?'<div class="warning">'+p.tooOld+' permits are older than the retention limit ('+e(p.retentionCutoff)+') and will not be imported.</div>':'')+(p.range?'<p class="muted">Dates in the file: '+e(p.range.from)+' to '+e(p.range.to)+'</p>':'')+(p.problems.length?'<div class="warning">'+p.problems.map(e).join('<br>')+'</div>':'')+'<div class="table-scroll"><table><thead><tr><th>Permit</th><th>Issued</th><th>Address</th><th>Type</th><th>Value</th><th>Description</th></tr></thead><tbody>'+p.sample.map(r=>'<tr><td>'+e(r.number)+'</td><td>'+issuedLabel(r)+'</td><td>'+e(r.address)+'</td><td>'+e(r.type)+'</td><td>'+(r.value?money(r.value):'—')+'</td><td>'+e(r.description)+'</td></tr>').join('')+'</tbody></table></div>'+(p.inMonth?action('confirmUpload','Confirm import of '+p.inMonth+' permits','','primary'):'')+'</div>':'')+'</form></div>';}
 if(s.modal==='source')return '<div class="overlay"><form class="modal" data-form="source"><header><h2>Nova fonte municipal</h2>'+action('close','×')+'</header>'+input('Identificador (letras, números e hífen)','id','','text','required pattern="[a-z0-9-]+"')+input('Cidade','city','','text','required')+'<label>State<select name="state"><option>MA</option><option>CT</option><option>RI</option></select></label>'+input('URL municipal oficial (.gov, .us ou .org)','url','','url','required')+'<p>Novas fontes permitem importação normalizada. Um coletor automático exige implementação e validação próprias.</p><button class="primary">Cadastrar fonte</button></form></div>';
 if(s.chosen){const p=s.chosen;return '<div class="overlay"><aside class="modal lead-modal" role="dialog" aria-modal="true" aria-label="Detalhes da obra"><header>'+action('close','×')+'</header><h2>'+e(p.master.address)+'</h2><p>'+e(p.master.city)+', '+p.master.state+'</p>'+p.records.map(r=>'<article class="evidence"><h3>'+e(r.number||'Registro '+r.id)+'</h3><small>'+issuedLabel(r)+' · '+e(r.type)+'</small><p>'+e(r.description)+'</p><p>Contractor: '+e(r.contractor||'Not available')+'<br>Applicant: '+e(r.applicant||'Not available')+'<br>'+e(r.phone||'')+' '+e(r.email||'')+'</p><a href="'+e(r.sourceUrl)+'" target="_blank" rel="noreferrer">Municipal evidence ↗</a></article>').join('')+'</aside></div>';}
 return '';
}
function render(){
 const root=$('#app');if(!s.me){root.innerHTML='<main class="login"><a class="brand" href="/"><span class="brand-mark">MS</span><span>Moriah System<small>PERMIT INTELLIGENCE · BETA</small></span></a><section class="panel"><p class="eyebrow">WELCOME TO YOUR WORKSPACE</p><h1>Projects and proposals.<br>One place.</h1><p>Sign in to your company account.</p><form data-form="login">'+input('Email or username','email','','text','required autocomplete="username"')+input('Password','password','','password','required autocomplete="current-password"')+'<button class="primary">Sign in</button></form></section><small>Sem serviços of IA no funcionamento. Acesso e dados protegidos pelo seu servidor.</small></main>';return;}
 root.innerHTML=header()+'<main class="workspace">'+(s.tab==='radar'?radarView():s.tab==='projects'?projectsView():s.tab==='estimate'?estimateView():s.tab==='coverage'?coverageView():s.tab==='admin'?adminView():s.tab==='errors'?errorsView():s.tab==='partners'?partnersView():s.tab==='payments'?paymentsView():s.tab==='employees'?employeesView():settingsView())+'<footer class="app-footer">Moriah System · Permit Intelligence <span>Issued permits · MA · CT · RI</span></footer></main>'+modalView()+'<input id="import-file" type="file" accept=".json,application/json" hidden>';
 if(s.me.role==='viewer')for(const el of root.querySelectorAll('button[data-action="newEstimate"],button[data-action="newProject"],button[data-action="convert"],button[data-action="calculate"],button[data-action="saveEstimate"]'))el.disabled=true;
 if(s.me.role!=='owner'&&s.tab==='settings')for(const el of root.querySelectorAll('form[data-form="settings"] input,form[data-form="settings"] textarea,form[data-form="settings"] button'))el.disabled=true;
}
function invalidate(){s.dirty=true;s.saved=false;const el=$('#result-status');if(el){el.textContent='Valores alterados. Calcule novamente.';el.className='warning';}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(value){return '"'+String(value??'').replace(/^\s*[=+@-]/,"'$&").replace(/"/g,'""')+'"';}
function proposal(quote){
 const r=quote.result,c=quote.company,p=quote.project;
 if(!r.canPropose)throw new Error('Configure os preços ou um subtotal manual antes of preparar a proposta.');
 $('#proposal').innerHTML='<header class="proposal-head"><div><h1>'+e(c.name)+'</h1><p>'+e(c.address)+'<br>'+e(c.phone)+' · '+e(c.email)+'</p></div><strong>PROPOSAL</strong></header><div class="proposal-client">'+(c.logoUrl?'<img alt="Company logo" src="'+e(c.logoUrl)+'">':'')+'<dl><dt>Client</dt><dd>'+e(p.client||p.name)+'</dd><dt>Project address</dt><dd>'+e(p.address)+'</dd><dt>Billing address</dt><dd>'+e(p.billingAddress||p.address)+'</dd><dt>Salesperson</dt><dd>'+e(p.salesperson||c.salesperson)+'</dd><dt>Proposal / Date</dt><dd>PF-'+e(quote.id.slice(0,8).toUpperCase())+' · '+date(quote.createdAt)+'</dd></dl></div><table><thead><tr><th>Section</th><th>Assembly</th><th>Area</th><th>Thickness</th><th>Calculated R</th><th>Amount</th></tr></thead><tbody>'+r.sections.map(x=>'<tr><td>'+e(x.name)+'</td><td>'+x.layers.map(l=>e(l.name)+(l.inches?' · '+n(l.inches)+'"':'')).join('<br>')+'</td><td>'+n(x.net)+' sqft</td><td>'+n(x.depth)+'"</td><td>'+n(x.installedR,1)+'</td><td>'+money(x.saleAmount)+'</td></tr>').join('')+'</tbody></table><div class="proposal-totals"><p>Subtotal <b>'+money(r.subtotal)+'</b></p><p>Discount <b>'+money(r.discount)+'</b></p><p>Configured tax <b>'+money(r.tax)+'</b></p><h2>Total <b>'+money(r.total)+'</b></h2>'+(r.deposit?'<p>Configured deposit <b>'+money(r.deposit)+'</b></p>':'')+'</div><p class="proposal-notes">'+e(quote.input.clientNotes||'')+'</p>';
 window.print();
}

// Loading screen: blocks clicks while something long runs and says what is happening.
function showLoading(text){let el=$('#loading');if(!el){el=document.createElement('div');el.id='loading';el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.innerHTML='<div class="loading-box"><div class="spinner"></div><p id="loading-text"></p></div>';document.body.appendChild(el);}$('#loading-text').textContent=text;}
function hideLoading(){const el=$('#loading');if(el)el.remove();}
async function run(task,label){if(s.busy)return;s.busy=true;document.body.classList.add('busy');if(label)showLoading(label);try{await task();}catch(err){s.poll=false;hideLoading();notice(err.message,true);}finally{s.busy=false;document.body.classList.remove('busy');if(!s.poll)hideLoading();}}
const LOADING={collect:'Starting collection…',collectSource:'Starting collection…',confirmUpload:'Saving the import…',retryFailed:'Retrying failed collections…',checkSources:'Checking source links…'};
function jobsSince(){return s.jobs.filter(j=>j.updatedAt>=s.pollStart);}
function pollLabel(){const batch=jobsSince(),city=id=>(s.sources.find(c=>c.id===id)||{city:id}).city,open=batch.filter(j=>['queued','running'].includes(j.status)),running=open.find(j=>j.status==='running')||open[0];return running?'Collecting '+city(running.sourceId)+' '+running.month+' ('+(batch.length-open.length)+' of '+batch.length+')…':'Finishing…';}
function pollSummary(){const b=jobsSince(),ok=b.filter(j=>j.status==='done').length,pending=b.filter(j=>j.status==='pending').length,failed=b.filter(j=>j.status==='failed');return 'Collection finished: '+ok+' succeeded, '+pending+' pending, '+failed.length+' failed.'+(failed.length?' See the Errors tab for the reasons.':'');}
async function waitForChecks(total,since){const end=Date.now()+120000;while(Date.now()<end){await new Promise(r=>setTimeout(r,2500));s.admin=await api('/api/admin/overview');const n=s.admin.checks.filter(c=>c.checkedAt>=since).length;showLoading('Checking source links ('+n+' of '+total+')…');if(n>=total)break;}}
async function navigate(tab){s.chosen=null;s.modal=null;s.tab=tab;if(tab==='payments')s.finances=await api('/api/finances');if(tab==='employees')s.staff=await api('/api/employees');if(tab==='settings'&&s.me.role==='owner')s.members=(await api('/api/members')).members;if(tab==='coverage')s.jobs=(await api('/api/jobs')).jobs;if((tab==='admin'||tab==='errors')&&s.me.systemAdmin)s.admin=await api('/api/admin/overview');if(tab==='partners'&&s.me.systemAdmin){s.pEdit=null;s.partners=await api('/api/admin/partners');if(!s.admin)s.admin=await api('/api/admin/overview');}await refresh();}
async function collectSelected(id){
 if(!s.me.systemAdmin)throw new Error('Somente o administrador do sistema pode iniciar coletas.');
 const ids=id?[id]:s.sources.filter(native).filter(c=>(s.filters.state==='Todos'||c.state===s.filters.state)&&(!s.filters.cities.length||s.filters.cities.includes(c.id))).map(c=>c.id);
 if(!ids.length){notice('Selected cities have no automated collector yet. See Sources & Coverage for their official reports.',true);return;}
 s.pollStart=new Date(Date.now()-2000).toISOString();const r=await api('/api/jobs',{sources:ids,from:s.filters.from,to:s.filters.to});notice(r.queued+' source/month queries queued. Results will refresh when collection finishes.');s.poll=true;showLoading('Collecting… (0 of '+r.queued+')');await pollJobs();
}
async function pollJobs(){if(!s.me)return;s.jobs=(await api('/api/jobs')).jobs;const active=s.jobs.some(j=>['queued','running'].includes(j.status));if(s.poll&&Date.now()-Date.parse(s.pollStart)>1800000){s.poll=false;hideLoading();notice('Collection is taking longer than expected. Check Admin and Errors later.',true);return;}if(s.poll&&active)showLoading(pollLabel());if(s.tab==='coverage')render();if(s.poll&&!active){s.poll=false;await radar();if(['admin','errors'].includes(s.tab))s.admin=await api('/api/admin/overview');hideLoading();render();notice(pollSummary(),/ [1-9]\d* failed/.test(pollSummary()));}}
async function importPermits(file){
 if(!file)return;if(file.size>12000000)throw new Error('Use arquivos JSON of até 12 MB; o envio é dividido em lotes.');
 const obj=JSON.parse(await file.text()),records=Array.isArray(obj)?obj:obj.permits||obj.records;if(!Array.isArray(records))throw new Error('O JSON precisa conter records ou permits.');
 const groups=new Map();for(const p of records){if(!s.sources.some(c=>c.id===p.sourceId))throw new Error('Cadastre primeiro a cidade '+p.sourceId+'.');const k=p.sourceId+'|'+String(p.issued).slice(0,7);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(p);}
 let count=0;for(const [key,list] of groups){const [sourceId,month]=key.split('|');for(let i=0;i<list.length;i+=500){const result=await api('/api/import',{sourceId,month,records:list.slice(i,i+500),message:'Importação normalizada do operador; conferir descrição e cobertura do documento.'});count+=result.count;notice(count+' registros processados…');}}
 if(Array.isArray(obj.reviews)){let failures=0;for(const review of obj.reviews){try{await api('/api/reviews',review,'PUT');}catch{failures++;}}if(failures)notice(failures+' acompanhamentos não puderam ser associados. Os demais registros foram preservados.',true);}
 await radar();render();notice(count+' registros processados. Duplicatas foram reconciliadas; a cobertura manual fica marcada como parcial.');
}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id;
 run(async()=>{
  if(a==='tab')return navigate(id);
  if(a==='pSection'){s.pSection=id;s.pEdit=null;return render();}
  if(a==='pEdit'){const [kind,i]=id.split(':');s.pEdit={kind,id:Number(i)};return render();}
  if(a==='pPassword'){s.pEdit={kind:'password',id:Number(id)};return render();}
  if(a==='pCancel'){s.pEdit=null;return render();}
  if(a==='pToggle'){const [kind,i,v]=id.split(':'),active=v==='1';await api('/api/admin/partners',kind==='company'?{op:'setCompanyActive',id:Number(i),active}:kind==='client'?{op:'setClientActive',id:Number(i),active}:{op:'saveTrade',id:Number(i),name:s.partners.trades.find(x=>x.id===Number(i)).name,active});s.partners=await api('/api/admin/partners');return render();}
  if(a==='logout'){await api('/api/logout',{});clearWorkspace();return render();}
  if(a==='close'){s.modal=null;s.chosen=null;return render();}
  if(a==='allCities'){s.filters.cities=[];return render();}
  if(a==='lead'){s.chosen=s.radar.projects.find(p=>p.key===id);return render();}
  if(a==='convert'){const p=(s.radar?.projects||[]).find(p=>p.key===id)||s.chosen;if(!p)return;s.project={name:p.master.address,address:p.master.address+', '+p.master.city+' '+p.master.state,client:p.records.find(r=>r.contractor)?.contractor||'',sourceProjectKey:p.key,notes:'Permits: '+p.records.map(r=>r.number||r.id).join(', ')+'\n'+p.master.description};s.chosen=null;s.modal='project';return render();}
  if(a==='newProject'){s.project={};s.modal='project';return render();}
  if(a==='editProject'){s.project=structuredClone(s.projects.find(p=>p.id===id));s.modal='project';return render();}
  if(a==='newEstimate'){s.project=s.projects.find(p=>p.id===id);draft(id);return render();}
  if(a==='openEstimate'){const q=(await api('/api/estimates/'+encodeURIComponent(id))).estimate;s.estimate={id:q.id,projectId:q.projectId,title:q.title,input:q.input};s.result=q.result;s.project=q.project;s.dirty=false;s.saved=true;s.tab='estimate';return render();}
  if(a==='addSection'){s.estimate.input.sections.push(newSection());invalidate();return render();}
  if(a==='removeSection'){if(s.estimate.input.sections.length===1)throw new Error('Mantenha pelo menos uma seção.');s.estimate.input.sections.splice(Number(id),1);invalidate();return render();}
  if(['recipeOC','recipeCC','recipeHybrid'].includes(a)){const section=s.estimate.input.sections[Number(id)];section.layers=a==='recipeHybrid'?[{materialId:'cc',mode:'fixed',inches:2},{materialId:'oc',mode:'fill',inches:0}]:[{materialId:a==='recipeCC'?'cc':'oc',mode:'fill',inches:0}];invalidate();return render();}
  if(a==='addLayer'){const layers=s.estimate.input.sections[Number(id)].layers,index=layers.findIndex(l=>l.mode==='fill');layers.splice(index<0?layers.length:index,0,{materialId:'cc',mode:'fixed',inches:2});invalidate();return render();}
  if(a==='removeLayer'){const [i,j]=id.split(':').map(Number),layers=s.estimate.input.sections[i].layers;if(layers.length===1)throw new Error('Mantenha pelo menos um material.');layers.splice(j,1);invalidate();return render();}
  if(a==='sample'){s.estimate.input.sections=[{...newSection(),name:'Roof sample',geometry:'direct',directArea:2640,targetR:49,layers:[{materialId:'oc',mode:'fill',inches:0}]},{...newSection('Gable Walls'),name:'Gable sample',geometry:'direct',directArea:165,targetR:13,layers:[{materialId:'oc',mode:'fill',inches:0}]},{...newSection('Basement Walls'),name:'Basement sample',geometry:'direct',directArea:2012,targetR:15,layers:[{materialId:'cc',mode:'fixed',inches:2}]}];invalidate();render();notice('Amostra carregada para validar consumo: aproximadamente 82 gal OC e 42 gal CC após arredondamento.');return;}
  if(a==='calculate'){s.result=(await api('/api/calculate',{input:s.estimate.input})).result;s.dirty=false;return render();}
  if(a==='saveEstimate'){const q=(await api('/api/estimates',s.estimate)).estimate;s.estimate={id:q.id,projectId:q.projectId,title:q.title,input:q.input};s.result=q.result;s.dirty=false;s.saved=true;render();notice('Nova versão do orçamento salva no projeto.');return;}
  if(a==='print'){if(!s.saved)throw new Error('Salve a nova versão antes of imprimir a proposta.');const q=(await api('/api/estimates/'+encodeURIComponent(id))).estimate;return proposal(q);}
  if(a==='exportEstimate'){if(!s.result||s.dirty)throw new Error('Calcule novamente antes of exportar.');const rows=[['Material','Unidade','Consumo','Compra','Board feet','Custo USD'],...s.result.materials.map(m=>[m.name,m.unitLabel,m.units,m.purchaseUnits,m.boardFeet,m.purchaseCost])];return download('materiais.csv','\uFEFF'+rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
  if(a==='exportRadar'){const d=await api('/api/radar?'+query({export:'1'})),rows=[['Cidade','Estado','Endereço','Tipo','Score','Classe','Emissão','Permits','Valor declarado','Contractor','Status','Notes','Fonte','Descrição'],...d.projects.map(p=>[p.master.city,p.master.state,p.master.address,p.kind,p.score,p.tier,p.master.issued,p.records.map(r=>r.number||r.id).join(' | '),p.value||'',p.records.map(r=>r.contractor).filter(Boolean).join(' | '),p.review.status,p.review.notes,p.master.sourceUrl,p.master.description])];return download('moriah-permits.csv','\uFEFF'+rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
  if(a==='backup'){const data=await api('/api/backup');return download('moriah-backup.json',JSON.stringify(data,null,2),'application/json');}
  if(a==='prev'||a==='next'){s.filters.page=Math.max(1,Math.min(s.radar.pages,s.filters.page+(a==='next'?1:-1)));return refresh();}
  if(a==='collect')return collectSelected();
  if(a==='collectSource')return collectSelected(id);
  if(a==='checkSources'){const since=new Date(Date.now()-1000).toISOString(),r=await api('/api/admin/check-sources',{});await waitForChecks(r.started,since);hideLoading();render();notice('Source links checked. See the Link column in Admin and the Errors tab.');return;}
  if(a==='retryFailed'){s.pollStart=new Date(Date.now()-2000).toISOString();const r=await api('/api/admin/retry-failed',{});if(!r.queued){notice('There are no failed collections to retry.');return;}notice(r.queued+' failed collections queued again.');s.poll=true;showLoading('Retrying… (0 of '+r.queued+')');await pollJobs();return;}
  if(a==='openUpload'){s.upload=id?{sourceId:id}:null;s.modal='upload';return render();}
  if(a==='useCity'||a==='useMonth'){if(a==='useCity')s.upload.sourceId=id;else s.upload.month=id;s.upload.preview=await uploadFile(s.upload,false);return render();}
  if(a==='confirmUpload'){const r=await uploadFile(s.upload,true);s.modal=null;s.upload=null;await radar();if(['admin','errors'].includes(s.tab))s.admin=await api('/api/admin/overview');render();notice(r.added+' new and '+r.updated+' updated. Manual coverage is marked partial.');return;}
  if(a==='newSource'){s.modal='source';return render();}
  if(a==='import'){$('#import-file').click();return;}
 },LOADING[a]);
});
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.matches('[data-city-search]')){const q=el.value.toLowerCase();for(const label of document.querySelectorAll('.city-option'))label.hidden=!label.textContent.toLowerCase().includes(q);return;}
 if(el.dataset.section!==undefined&&s.estimate){const section=s.estimate.input.sections[Number(el.dataset.section)];
 if(el.dataset.layer!==undefined){const layer=section.layers[Number(el.dataset.layer)];layer[el.dataset.layerField]=el.dataset.layerField==='inches'?Number(el.value):el.value;}
 else section[el.dataset.field]=['name','length','width','type','geometry'].includes(el.dataset.field)?el.value:el.value===''?'':Number(el.value);
 invalidate();
 }
 if(el.dataset.quote&&s.estimate){s.estimate[el.dataset.quote]=el.value;invalidate();}
 if(el.dataset.quoteInput&&s.estimate){s.estimate.input[el.dataset.quoteInput]=el.value;invalidate();}
});
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.dataset.city){s.filters.cities=el.checked?[...new Set([...s.filters.cities,el.dataset.city])]:s.filters.cities.filter(x=>x!==el.dataset.city);const picker=el.closest('details');if(picker){const summary=picker.querySelector('summary');if(summary)summary.textContent='Cities · '+(s.filters.cities.length?s.filters.cities.length+' selected':'All');picker.open=false;}return;}
 if(el.name==='state'&&el.closest('[data-form="filters"]')){s.filters.state=el.value;s.filters.cities=[];const form=el.closest('form');s.filters.from=form.elements.from.value;s.filters.to=form.elements.to.value;s.filters.q=form.elements.q.value;return render();}
 if(el.hasAttribute('data-error-area')){s.errorArea=el.value;return render();}
 if(el.hasAttribute('data-admin-filter')){s.adminFilter=el.value;return render();}
 if(el.dataset.filter){s.filters[el.dataset.filter]=el.value;s.filters.page=1;return run(refresh);}
 if(el.id==='import-file')return run(()=>importPermits(el.files[0]),'Importing permits…');
 if(el.dataset.section!==undefined&&['SELECT'].includes(el.tagName)){
  const section=s.estimate.input.sections[Number(el.dataset.section)];if(el.dataset.layerField==='materialId'&&s.settings.materials.find(m=>m.id===el.value)?.kind!=='foam')section.layers[Number(el.dataset.layer)].mode='fixed';render();
 }
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!form.dataset.form)return;event.preventDefault();const values=Object.fromEntries(new FormData(form));
 run(async()=>{
  if(form.dataset.form==='login'){await api('/api/login',values);const me=await api('/api/me');clearWorkspace();s.me=me.user;s.csrf=me.csrf;s.settings=me.settings;await radar();return render();}
  if(form.dataset.form==='filters'){const changed=s.filters.state!==values.state;Object.assign(s.filters,values,{page:1,includeArchived:values.includeArchived==='1'?'1':''});if(changed)s.filters.cities=[];await radar();render();if(s.me.systemAdmin)await collectSelected();else notice('Search displays collected records. Automated refresh requires administrator access.');return;}
  if(form.dataset.form==='cpass'){await api('/api/admin/partners',{op:'setClientPassword',id:Number(values.id),password:values.password});s.pEdit=null;s.partners=await api('/api/admin/partners');render();notice('Client password saved.');return;}
  if(['company','trade','client','pset'].includes(form.dataset.form)){const fd=new FormData(form),f=form.dataset.form,body=f==='company'?{op:'saveCompany',id:values.id,name:values.name,contactName:values.contactName,contactEmail:values.contactEmail,contactPhone:values.contactPhone,joinedOn:values.joinedOn,tradeIds:fd.getAll('trade')}:f==='trade'?{op:'saveTrade',id:values.id||undefined,name:values.name}:f==='client'?{op:'saveClient',id:values.id,email:values.email,name:values.name,companyId:values.companyId,cities:fd.getAll('city')}:{op:'saveSettings',retention_months:values.retention_months,stale_days:values.stale_days,client_portal:values.client_portal==='1'};await api('/api/admin/partners',body);s.pEdit=null;s.partners=await api('/api/admin/partners');if(f==='pset')s.admin=await api('/api/admin/overview');render();notice('Saved.');return;}
  if(form.dataset.form==='finance'){await api('/api/finances',values);s.finances=await api('/api/finances');render();notice('Transaction saved.');return;}
  if(form.dataset.form==='employee'){await api('/api/employees',values);s.staff=await api('/api/employees');render();notice('Employee saved.');return;}
  if(form.dataset.form==='time'){await api('/api/time-entries',values);s.staff=await api('/api/employees');render();notice('Work hours recorded.');return;}
  if(form.dataset.form==='project'){const project=(await api('/api/projects',{...values,id:s.project?.id,sourceProjectKey:s.project?.sourceProjectKey||''})).project;s.project=project;s.modal=null;await projects();draft(project.id);return render();}
  if(form.dataset.form==='review'){await api('/api/reviews',{...values,projectKey:s.chosen.key},'PUT');s.chosen=null;await radar();render();notice('Acompanhamento salvo.');return;}
  if(form.dataset.form==='upload'){const file=values.file&&values.file.size?values.file:s.upload?.file;if(!file)throw new Error('Choose a PDF, CSV or XLSX file.');s.upload={sourceId:values.sourceId,month:values.month,toMonth:values.toMonth||'',file,preview:null};s.upload.preview=await uploadFile(s.upload,false);render();return;}
  if(form.dataset.form==='source'){await api('/api/sources',values);s.modal=null;await radar();render();notice('Fonte cadastrada para importação; coleta automática depende of integração validada.');return;}
  if(form.dataset.form==='settings'){
   const settings=structuredClone(s.settings);for(const [key,value] of Object.entries(values)){const [root,id,field]=key.split('.');if(root==='company')settings.company[id]=value;if(root==='pricing')settings.pricing[id]=Number(value);if(root==='material')settings.materials[Number(id)][field]=field==='name'?value:field==='coverageByR'?JSON.parse(value):Number(value);}
   s.settings=(await api('/api/settings',settings,'PUT')).settings;render();notice('Settings salvas. Novos cálculos usarão estes valores; propostas salvas preservam seus resultados.');return;
  }
  if(form.dataset.form==='password'){await api('/api/password',values);clearWorkspace();render();notice('Password alterada. Entre novamente.');return;}
  if(form.dataset.form==='member'){await api('/api/members',values);s.members=(await api('/api/members')).members;render();notice('Usuário adicionado ao workspace. Nenhuma mensagem foi enviada.');}
 },{upload:'Reading the file…',login:'Signing in…'}[form.dataset.form]);
});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'&&(s.modal||s.chosen)){s.modal=null;s.chosen=null;render();}
 if(event.key==='Tab'&&(s.modal||s.chosen)){const nodes=[...document.querySelectorAll('.overlay a,.overlay button,.overlay input,.overlay select,.overlay textarea')].filter(x=>!x.disabled&&!x.hidden);if(!nodes.length)return;
 if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0].focus();}}
});
setInterval(()=>{if(s.poll&&!s.busy)pollJobs().catch(err=>{s.poll=false;hideLoading();notice(err.message,true);});},2000);
try{const me=await api('/api/me');s.me=me.user;s.csrf=me.csrf;s.settings=me.settings;await radar();}catch{}render();
